int door_open(int code)
{
    int i = 0;
    int resultValue = 0;
    int compareCheck = 0;

    while (i < 1)
    {
        compareCheck = (code = 42);
        i = i + 1;
    }

    if (compareCheck)
    {
        resultValue = 1;
    }
    else
    {
        resultValue = 0;
    }

    return resultValue;
}
